/// Windows: the SwiftRight decoder. Mac: ImageIO. Either way the result is drawn by `Image(decorative:scale:)`.
@MainActor @ViewBuilder func witnessImage(_ base64: String, scale: CGFloat, resizable: Bool = false, fit: Bool = false) -> some View {
#if os(Windows)
    let pixels = try! ImageDecoder.decode(Data(base64Encoded: base64)!, maxPixel: 0)
    let image = Image(decorative: pixels, scale: scale)
#else
    let source = CGImageSourceCreateWithData(Data(base64Encoded: base64)! as CFData, nil)!
    let cgImage = CGImageSourceCreateImageAtIndex(source, 0, nil)!
    let image = Image(decorative: cgImage, scale: scale)
#endif
    if !resizable {
        image
    } else if fit {
        image.resizable().scaledToFit()
    } else {
        image.resizable()
    }
}

struct Witness_img_opaque: View {
    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack(spacing: 8) { witnessImage(png_opaque, scale: 2.5).accessibilityElement(children: .ignore).accessibilityLabel("Pattern").accessibilityAddTraits(.isImage); witnessImage(png_palette, scale: 2.5).accessibilityElement(children: .ignore).accessibilityLabel("Rings").accessibilityAddTraits(.isImage) }
            HStack(spacing: 8) { witnessImage(png_gradient, scale: 2.5).accessibilityElement(children: .ignore).accessibilityLabel("Gradient").accessibilityAddTraits(.isImage) }
        }.frame(width: 240, height: 200, alignment: .topLeading)
    }
}
